<?php
namespace App\Livewire\Support;
use App\Models\FeatureRequest;
use Livewire\Component;
use Livewire\WithPagination;
class FeatureRequestCenter extends Component { use WithPagination; public string $title=''; public string $description=''; public ?int $replyId=null; public string $response=''; private function handler():bool{return auth()->user()->hasRole('super-admin');} public function submit():void { abort_unless(auth()->user()->hasAnyRole(['school-admin','headteacher','principal','deputy-headteacher','deputy','teacher','class-teacher','pre-primary-teacher','lower-primary-teacher','upper-primary-teacher','junior-secondary-teacher']),403); $this->validate(['title'=>'required|string|max:180','description'=>'required|string|max:5000']); FeatureRequest::create(['requested_by'=>auth()->id(),'title'=>$this->title,'description'=>$this->description]); $this->reset(['title','description']); session()->flash('success','Feature request sent to the platform team.'); } public function reply(int $id):void{abort_unless($this->handler(),403);$this->replyId=$id;$this->response=(string)FeatureRequest::withoutSchoolScope()->findOrFail($id)->admin_response;} public function saveReply():void{abort_unless($this->handler(),403);$this->validate(['response'=>'required|string|max:5000']);FeatureRequest::withoutSchoolScope()->findOrFail($this->replyId)->update(['admin_response'=>$this->response,'status'=>'reviewed','responded_by'=>auth()->id()]);$this->reset(['replyId','response']);session()->flash('success','Feature-request response saved.');} public function render(){ $q=FeatureRequest::with('requester')->latest(); if($this->handler())$q=$q->withoutSchoolScope(); return view('livewire.support.feature-request-center',['requests'=>$q->paginate(15),'isHandler'=>$this->handler()])->layout($this->handler()?'layouts.admin':(request()->routeIs('teacher.*')?'layouts.teacher':'layouts.admin'));}}
